 if(!paused){if(state.event)toast(state.event);if(state.effect){burst(pos.clone().addScaledVector(up,1));if(state.effect==='hot')speakHot();else tone(state.effect==='star'?720:420);}if(state.mode!==lastMode&&walking)clearControls();lastMode=state.mode;for(const p of particles){if(p.life>0){p.life-=dt;p.mesh.position.addScaledVector(p.v,dt);p.mesh.rotation.y+=dt*2;p.mesh.visible=p.life>0;}}if(!walking&&(trailTick+=dt)>.045){trailTick=0;particle(pos,new THREE.Vector3((rand()-.5),-.3,(rand()-.5)),1.2);}}
 // Parallel-transported north keeps walking and the camera smooth over the poles.
 const desiredTarget=pos.clone().addScaledVector(up,1);target.lerp(desiredTarget,1-Math.exp(-dt*6));cameraUp.applyQuaternion(new THREE.Quaternion().slerp(new THREE.Quaternion().setFromUnitVectors(cameraUp,up),1-Math.exp(-dt*5))).normalize();cameraNorth.lerp(north,1-Math.exp(-dt*5));cameraNorth.addScaledVector(cameraUp,-cameraNorth.dot(cameraUp)).normalize();if(cameraNorth.lengthSq()<.1)cameraNorth.copy(north);const right=cameraNorth.clone().cross(cameraUp).normalize(),back=cameraNorth.clone().multiplyScalar(-Math.cos(yaw)).addScaledVector(right,Math.sin(yaw));const wanted=walking?distance:state.mode==='flight'?Math.max(distance,33):Math.max(distance,30);cameraDistance+=(wanted-cameraDistance)*(1-Math.exp(-dt*3));camera.position.copy(target).addScaledVector(back,cameraDistance*Math.cos(pitch)).addScaledVector(cameraUp,cameraDistance*Math.sin(pitch));camera.up.copy(cameraUp);camera.lookAt(target);
